{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table Maplemonk.Hyuman_DRR_Sales_Consolidated_Intermediate as select \'Uniware\' as source ,Date(order_date) as Order_date ,sku ,marketplace ,product_name_final ,product_category ,case when marketplace =\'MEESHO_BLR\' then \'SR-Banglore\' when marketplace =\'MEESHO_GGN\' then \'SR-Gurgoan\' when marketplace =\'MEESHO_MUM\' then \'SR-Mumbai\' when marketplace =\'FIRSTCRY_MUM\' then \'SR-Mumbai\' when marketplace =\'SHOPIFY_MUM\' then \'SR-Mumbai\' when marketplace =\'SMYTTEN_MUM\' then \'SR-Mumbai\' when marketplace =\'AMAZON_FLEX_API_MUM\' then \'SR-Mumbai\' when marketplace =\'AMAZON_FLEX_API_BLR\' then \'SR-Banglore\' when marketplace =\'AMAZON_FLEX_API_GGN\' then \'SR-Gurgoan\' when marketplace =\'AMAZON_FLEX_API_KOL\' then \'SR-Kolkata\' when marketplace =\'MYNTRAPPMP_GGN\' then \'SR-Gurgoan\' when marketplace =\'MYNTRAPPMP_BLR\' then \'SR-Banglore\' when marketplace =\'MYNTRAPPMP_MUM\' then \'SR-Mumbai\' when marketplace =\'MYNTRAPPMP_KOL\' then \'SR-Kolkata\' when marketplace =\'FLIPKART\' then \'SR-Kolkata\' when marketplace =\'FLIPKART_MUM\' then \'SR-Mumbai\' when marketplace =\'FLIPKART_GGN1\' then \'SR-Gurgoan\' when marketplace =\'FLIPKART_GGN\' then \'SR-Gurgoan\' when marketplace =\'FLIPKART_BLR\' then \'SR-Banglore\' when marketplace =\'AMAZON_IN_API\' then \'AMAZON\' when marketplace =\'CUSTOM\' then \'CUSTOM\' else marketplace end as Facility ,sum(cast(suborder_quantity as int64)) Units_Sold ,sum(cast(selling_price as float64)) Selling_Price from hyuman-wh.maplemonk.hyuman_UNICOMMERCE_fact_items where UPPER(order_status) not in (\'CANCELLED\',\'LOCATION_NOT_SERVICEABLE\') group by 1,2,3,4,5,6,7 union all select shop_name as source ,Date(order_date) Order_date ,sku ,fulfilment_source as Marketplace ,Product_name_final ,category ,case when fulfilment_source = \'malur_bts\' then \'FBF-Banglore\' when fulfilment_source = \'bhi_vas_wh_nl_01nl\' then \'FBF-Mumbai\' when fulfilment_source = \'ulub_bts\' then \'FBF-Kolkata\' when fulfilment_source = \'gur_san_wh_nl_01nl\' then \'FBF-Gurgoan\' else fulfilment_source end as Facility ,sum(cast(quantity as int64)) Units_sold ,sum(cast(line_item_sales as Float64)) as Selling_price from maplemonk.hyuman_flipkart_fact_items where UPPER(order_item_status) NOT IN(\'RETURNED\',\'CANCELLED\',\'RETURN REQUESTED\',\'UNDELIVERED\') and fulfilment_type = \'FBF\' group by 1,2,3,4,5,6,7 union all select \'Blinkit\' as source ,Date(order_date) Order_date ,commonsku as sku ,\'Blinkit\' as Marketplace ,product_name ,category ,\'Blinkit\' as Facility ,sum(cast(quantity as int64)) as Units_sold ,sum(cast(Selling_price as Float64)) Selling_Price from MapleMonk.Hyuman_Blinkit_Fact_items group by 1,2,3,4,5,6,7; Create or replace table Maplemonk.Hyuman_DRR_Sales_Consolidate as WITH source_Latest_Date AS ( SELECT source, MAX(DATE(order_date)) AS Latest_Date FROM Maplemonk.Hyuman_DRR_Sales_Consolidated_Intermediate GROUP BY 1 ), base AS ( SELECT source, sku, marketplace, product_name_final, product_category, facility, DATE(order_date) AS order_date, SUM(IFNULL(units_sold,0)) AS units_sold, SUM(IFNULL(selling_price,0)) AS selling_price FROM Maplemonk.Hyuman_DRR_Sales_Consolidated_Intermediate GROUP BY 1,2,3,4,5,6,7 ) SELECT b.source, b.sku, b.marketplace, b.facility, b.product_name_final, b.product_category, r.Latest_Date, SUM( CASE WHEN b.order_date BETWEEN DATE_SUB(r.Latest_Date, INTERVAL 6 DAY) AND r.Latest_Date THEN b.units_sold ELSE 0 END) AS Sold_Quantity_7_Days, SUM( CASE WHEN b.order_date BETWEEN DATE_SUB(r.Latest_Date, INTERVAL 6 DAY) AND r.Latest_Date THEN b.selling_price ELSE 0 END) AS Selling_Price_7_Days, SUM( CASE WHEN b.order_date BETWEEN DATE_SUB(r.Latest_Date, INTERVAL 13 DAY) AND r.Latest_Date THEN b.units_sold ELSE 0 END ) AS Sold_Quantity_14_Days, SUM( CASE WHEN b.order_date BETWEEN DATE_SUB(r.Latest_Date, INTERVAL 13 DAY) AND r.Latest_Date THEN b.selling_price ELSE 0 END ) AS Selling_Price_14_Days, SUM( CASE WHEN b.order_date BETWEEN DATE_SUB(r.Latest_Date, INTERVAL 27 DAY) AND r.Latest_Date THEN b.units_sold ELSE 0 END) AS Sold_Quantity_28_Days, SUM( CASE WHEN b.order_date BETWEEN DATE_SUB(r.Latest_Date, INTERVAL 27 DAY) AND r.Latest_Date THEN b.selling_price ELSE 0 END ) AS Selling_Price_28_Days, SUM( CASE WHEN b.order_date BETWEEN DATE_SUB(r.Latest_Date, INTERVAL 55 DAY) AND r.Latest_Date THEN b.units_sold ELSE 0 END) AS Sold_Quantity_56_Days, SUM( CASE WHEN b.order_date BETWEEN DATE_SUB(r.Latest_Date, INTERVAL 55 DAY) AND r.Latest_Date THEN b.selling_price ELSE 0 END) AS Selling_Price_56_Days, SUM( CASE WHEN b.order_date BETWEEN DATE_SUB(r.Latest_Date, INTERVAL 89 DAY) AND r.Latest_Date THEN b.units_sold ELSE 0 END) AS Sold_Quantity_90_Days, SUM( CASE WHEN b.order_date BETWEEN DATE_SUB(r.Latest_Date, INTERVAL 89 DAY) AND r.Latest_Date THEN b.selling_price ELSE 0 END) AS Selling_Price_90_Days FROM base b JOIN source_Latest_Date r ON lower(b.source) = lower(r.source) GROUP BY 1,2,3,4,5,6,7",
                    "transaction": true
                }
            ) }}
